const cfg = $('Config').first().json;
const followed = new Set(String(cfg.followedPlayerIds || '').split(',')
  .map(s => Number(s.trim())).filter(n => n > 0));
const records = $input.all()
  .flatMap(i => Array.isArray(i.json.data) ? i.json.data : [i.json])
  .filter(r => r && r.id);
function setScores(score) {
  const g = score && score.games;
  if (!Array.isArray(g) || g.length !== 2 || !Array.isArray(g[0])) return [];
  return g[0].map((x, i) => `${x}-${g[1][i]}`);
}

// What the last run saw. Kept between runs only when the workflow is active.
const state = $getWorkflowStaticData('global');
const seen = state.liveMatches || {};
const now = {};
const out = [];
const total = s => s[0] + s[1];
for (const m of records) {
  const p1 = (m.players && m.players.p1) || {};
  const p2 = (m.players && m.players.p2) || {};
  if (!followed.has(p1.id) && !followed.has(p2.id)) continue;
  const names = `${p1.name} v ${p2.name}`;
  const where = [m.tournament, m.round].filter(Boolean).join(', ');
  const before = seen[m.id];
  const read = (m.score && Array.isArray(m.score.sets)) ? m.score.sets : null;
  if (!before) {
    now[m.id] = { sets: read || [0, 0], names, where };
    const line = setScores(m.score).join(' ');
    out.push({ json: { kind: 'started', matchId: m.id,
      text: `Live now: ${names} (${where}).` + (line ? ` Score ${line}.` : '') } });
    continue;
  }
  // No score this run, or a correction that took a set back: keep what we had, so the same
  // set is never announced twice. A correction that keeps the count is taken as it is.
  if (!read || total(read) < total(before.sets)) {
    now[m.id] = { sets: before.sets, names, where };
    continue;
  }
  now[m.id] = { sets: read, names, where };
  if (total(read) === total(before.sets)) continue;
  const gained1 = read[0] > before.sets[0], gained2 = read[1] > before.sets[1];
  const done = setScores(m.score).slice(0, total(read)).join(' ');
  const who = gained1 === gained2 ? 'Sets move on' : `Set to ${gained1 ? p1.name : p2.name}`;
  out.push({ json: { kind: 'set', matchId: m.id,
    text: `${who}: ${names}, sets ${read[0]}-${read[1]}` + (done ? ` (${done})` : '') + `. ${where}.` } });
}
// A followed match that left the live list has ended, or its scores have paused. Keep it and
// read it until it shows a result: every run for the first hour, then hourly for a day, then
// every six hours, for up to a week. That keeps a slow result from eating the daily allowance.
const HOUR = 3600 * 1000;
for (const id of Object.keys(seen)) {
  if (now[id]) continue;
  const gone = seen[id].goneSince || Date.now();
  const age = Date.now() - gone;
  if (age > 7 * 24 * HOUR) continue;
  now[id] = { ...seen[id], goneSince: gone };
  const every = age < HOUR ? 0 : age < 24 * HOUR ? HOUR : 6 * HOUR;
  if (seen[id].checkedAt && Date.now() - seen[id].checkedAt < every) continue;
  now[id].checkedAt = Date.now();
  out.push({ json: { kind: 'ended', matchId: Number(id) } });
}
state.liveMatches = now;
return out;

function setScores(score) {
  const g = score && score.games;
  if (!Array.isArray(g) || g.length !== 2 || !Array.isArray(g[0])) return [];
  return g[0].map((x, i) => `${x}-${g[1][i]}`);
}

function finalLine(m, winnerFirst) {
  const sets = setScores(m.score)
    .map(x => winnerFirst && m.winner === 2 ? x.split('-').reverse().join('-') : x);
  const last = sets[sets.length - 1];
  if (m.outcome === 'completed' && sets.length >= 3 && (last === '1-0' || last === '0-1')) {
    sets[sets.length - 1] = `${last} (match tiebreak)`;
  }
  return sets.join(' ');
}

const state = $getWorkflowStaticData('global');
const live = state.liveMatches || {};
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  // Not finished yet: it stays on the list and is read again next run.
  if (m.status !== 'completed') continue;
  const p1 = m.players.p1, p2 = m.players.p2;
  const where = [m.tournament, m.round].filter(Boolean).join(', ');
  if (!m.winner) {
    // Over, but no winner published yet: say so once, and keep reading until there is one.
    if (live[m.id] && !live[m.id].noResultSent) {
      live[m.id].noResultSent = true;
      out.push({ json: { text: `Ended without a result yet: ${p1.name} v ${p2.name}. ${where}.` } });
    }
    continue;
  }
  delete live[m.id];
  const won = m.winner === 1 ? p1 : p2, lost = m.winner === 1 ? p2 : p1;
  const how = m.outcome === 'retired' ? ' (retired)' : m.outcome === 'walkover' ? ' (walkover)' : '';
  const line = finalLine(m, true);
  out.push({ json: { text: `Final: ${won.name} beat ${lost.name}` + (line ? ` ${line}` : '') +
    `${how}. ${where}.` } });
}
state.liveMatches = live;
return out;
